(7686673, 1258277, 52549, '<td valign="top">Really amazing, beautiful image. Congrats.</td>', 'Really amazing, beautiful image. Congrats.', '2021-02-11 04:02:31.000000', NULL, 0),
(7686696, 1258345, 3306, '<td valign="top">Another amazing capture Roz. Besides the beautiful and unique insect, the dew drops set this picture apart from other insect macros. To show the wasp and the dew drops in focus at the same time requires great creativity and skill. It must be fun searching for these little critters!</td>', 'Another amazing capture Roz. Besides the beautiful and unique insect, the dew drops set this picture apart from other insect macros. To show the wasp and the dew drops in focus at the same time requires great creativity and skill. It must be fun searching for these little critters!', '2021-02-11 22:32:42.000000', NULL, 0),
(7703434, 1258191, 67145, '<td valign="top">i like this a lot .. !! .. <br/>they way you have composed the shot with the bridge and the reflection is brilliant .. <br/>i like the ripples in the water make the reflection of the bridge a bit jagged .. <br/>its great in sepia as well .. <br/> <br/>both pictures are wonderful .. <br/>but i like the one with your legs more .. just because it tells a story .. <br/>to me a photo that tells a story is hands down better than something that doesnt .. <br/>of course thats a generalization .. some pics dont need a story they can be so amazing . :)</td>', 'i like this a lot .. !! .. they way you have composed the shot with the bridge and the reflection is brilliant .. i like the ripples in the water make the reflection of the bridge a bit jagged .. its great in sepia as well ..  both pictures are wonderful .. but i like the one with your legs more .. just because it tells a story .. to me a photo that tells a story is hands down better than something that doesnt .. of course thats a generalization .. some pics dont need a story they can be so amazing . :)', '2021-10-15 00:07:16.000000', NULL, 0);
